def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue

            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1,y), (x+1,y), (x,y-1), (x,y+1)):
                    if (0 <= nx < h and 0 <= ny < w and
                            (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        q.append((nx, ny))

            r0 = min(x for x, _ in cells)
            r1 = max(x for x, _ in cells)
            c0 = min(y for _, y in cells)
            c1 = max(y for _, y in cells)

            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = {
                (x, y)
                for x in range(r0, r1+1)
                for y in range(c0, c1+1)
                if x in (r0, r1) or y in (c0, c1)
            }
            if set(cells) == perimeter:
                fill = 7 if (r1-r0+1) % 2 == 1 else 2
                for x in range(r0+1, r1):
                    for y in range(c0+1, c1):
                        out[x][y] = fill

    return out
